        private static void Pump(){if(EditorApplication.isPlaying)EditorApplication.QueuePlayerLoopUpdate();}
        private static IEnumerator Guard(IEnumerator e){var stack=new Stack<IEnumerator>();stack.Push(e);while(stack.Count>0){bool more;object current;try{more=stack.Peek().MoveNext();current=more?stack.Peek().Current:null;}catch(Exception ex){File.WriteAllText(Path.Combine(Root,"failed.txt"),ex.ToString());if(Unity.Services.Core.UnityServices.State==Unity.Services.Core.ServicesInitializationState.Initialized)try{AuthenticationService.Instance.SignOut(true);}catch{}EditorApplication.Exit(1);yield break;}if(!more){stack.Pop();continue;}if(current is IEnumerator inner)stack.Push(inner);else yield return current;}File.WriteAllText(Path.Combine(Root,"checks.json"),JsonUtility.ToJson(new CheckResult{Passed=true,Checks=checks.ToArray()},true));EditorApplication.Exit(0);}
        [Serializable]private sealed class CheckResult{public bool Passed;public string[] Checks;}
        private static void Check(bool value,string label){checks.Add((value?"PASS ":"FAIL ")+label);File.WriteAllLines(Path.Combine(Root,"checks.txt"),checks);if(!value)throw new InvalidOperationException(label);}
